licht.css:
body{font-family:'Inter','Segoe UI',Arial,sans-serif;}
h1,h2,h3{font-weight:600;letter-spacing:-.025em;}
.top{background:rgba(255,255,255,.94);color:var(--navy);border-bottom:1px solid var(--line);backdrop-filter:blur(8px);}
.menu a{color:var(--navy);} .menu a:hover{background:var(--sky);color:var(--navy);}
.hero,.crumb,.shero,.chero,.phero,.thx{background:#fff;color:var(--navy);}
.hero{border-bottom:1px solid var(--line);} .hero::after{display:none;}
.hero h1{font-weight:600;}
.eyebrow,.shero .eyebrow{color:var(--blue);}
.hero .lead,.crumb p,.shero p,.chero p,.phero p,.thx p{color:var(--muted);}
.thx p a{color:var(--blue);}
.btn.quiet{color:var(--navy);box-shadow:inset 0 0 0 1.5px var(--line);} .btn.quiet:hover{box-shadow:inset 0 0 0 1.5px var(--navy);}
.btn,.menu a.cta{border-radius:8px;}
.hero .emblem img{filter:none;}
.servicebar{background:var(--sky);color:var(--navy);}
.service,.card{border-radius:10px;} .service .num{background:var(--sky);color:var(--blue);}
.crumb .backlink{color:var(--muted);} .crumb .backlink:hover{background:var(--sky);color:var(--navy);}
.filters a{color:var(--navy);box-shadow:inset 0 0 0 1.5px var(--line);} .filters a:hover{color:var(--navy);box-shadow:inset 0 0 0 1.5px var(--navy);} .filters a.on{background:var(--navy);color:#fff;}
.ptags a{color:var(--navy);background:var(--sky);} .ptags a:hover{background:var(--line);}
.section.sky,.sec.sky{background:#fafafa;} .folder.a .tab,.folder.a .body{background:var(--navy);} .folder.a{color:#fff;}
.band{background:var(--sky);color:var(--navy);} .band p{color:var(--muted);}
.band .btn.white{background:var(--blue);color:#fff;} .band .btn.outline{color:var(--navy);box-shadow:inset 0 0 0 1.5px var(--navy);}
.foot{background:#fafafa;color:var(--muted);border-top:1px solid var(--line);} .nap{border-bottom-color:var(--line);} .nap strong{color:var(--navy);} .foot a:hover{color:var(--navy);} .legal .login{color:var(--muted);}

warm.css:
:root{--cream:#faf5ec;--cream-2:#f2e9da;--brown:#6b5d4f;--sand:#e4d7c2;}
body{font-family:'Nunito Sans','Segoe UI',Arial,sans-serif;background:var(--cream);}
h1,h2,h3{font-family:'Fraunces',Georgia,serif;font-weight:600;letter-spacing:-.01em;}
.top{background:var(--cream);color:var(--navy);border-bottom:1px solid var(--sand);}
.menu a{color:var(--navy);} .menu a:hover{background:var(--cream-2);color:var(--navy);}
.btn,.menu a.cta{border-radius:999px;}
.hero{background:var(--cream);color:var(--navy);} .hero::after{border-color:var(--blue);opacity:.1;}
.hero .lead{color:var(--brown);} .eyebrow,.shero .eyebrow{color:var(--blue);}
.btn.quiet{color:var(--navy);box-shadow:inset 0 0 0 1.5px var(--sand);} .btn.quiet:hover{box-shadow:inset 0 0 0 1.5px var(--navy);}
.hero .emblem img{filter:drop-shadow(0 18px 30px rgba(90,60,30,.18));}
.servicebar{background:var(--navy);color:#fff;}
.section{background:var(--cream);} .section.sky,.sec.sky{background:var(--cream-2);}
.service,.card{background:#fffdf8;border-color:var(--sand);border-radius:22px;}
.service .num{border-radius:50%;background:var(--blue);}
.folder .tab{border-radius:18px 18px 0 0;} .folder .body{border-radius:0 26px 26px 26px;} .photo-sheet,.photo-sheet img{border-radius:16px;}
.crumb,.shero,.chero,.phero,.thx{background:var(--cream-2);color:var(--navy);}
.crumb p,.shero p,.chero p,.phero p,.thx p{color:var(--brown);} .thx p a{color:var(--blue);}
.crumb .backlink{color:var(--brown);} .crumb .backlink:hover{background:var(--sand);color:var(--navy);}
.filters a{color:var(--navy);box-shadow:inset 0 0 0 1.5px var(--sand);} .filters a:hover{color:var(--navy);box-shadow:inset 0 0 0 1.5px var(--navy);} .filters a.on{background:var(--navy);color:#fff;}
.ptags a{background:#fffdf8;color:var(--navy);}
.cwrap{background:var(--cream-2);} .cform,.cside{border-radius:24px;} .cform{border-color:var(--sand);}
.others a{border-color:var(--sand);background:#fffdf8;}
.gallery .ph{border-radius:20px;}
.chatfab{border-radius:999px;}

etalage.css:
body{font-family:'Archivo','Segoe UI',Arial,sans-serif;}
h1,h2,h3{font-weight:800;letter-spacing:-.025em;}
.btn,.menu a.cta{border-radius:4px;}
.hero::after{display:none;}
.hero.has-photo{background-color:#000;background-size:cover;background-position:center;min-height:min(88vh,780px);display:flex;align-items:flex-end;padding-top:140px;}
.hero.has-photo::before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(0,0,0,.82) 0%,rgba(0,0,0,.6) 45%,rgba(0,0,0,.2) 100%),linear-gradient(180deg,rgba(0,0,0,0) 40%,rgba(0,0,0,.6) 100%);}
.hero.has-photo .wrap{grid-template-columns:1fr;width:100%;}
.hero.has-photo .emblem{display:none;}
.hero.has-photo .lead{color:rgba(255,255,255,.88);}
.hero h1{font-size:clamp(44px,7.6vw,96px);max-width:16ch;}
.service{border-radius:4px;} .service .num{border-radius:4px;}
.folder{padding-top:0;} .folder .tab{display:none;}
.folder .body{border-radius:6px;min-height:560px;background:#000 !important;}
.folder .body::before{content:"";position:absolute;inset:0;z-index:1;background:linear-gradient(180deg,rgba(0,0,0,0) 35%,rgba(0,0,0,.85) 100%);}
.folder .photo-sheet{inset:0;top:0;left:0;right:0;height:auto;transform:none;border-radius:0;padding:0;box-shadow:none;}
.folder .photo-sheet img{border-radius:0;transition:transform .5s ease;}
.folder:hover .photo-sheet{transform:none;} .folder:hover .photo-sheet img{transform:scale(1.04);}
.folder .photo-sheet.empty{background:var(--navy);}
.folder .front{z-index:2;} .folder .desc{color:rgba(255,255,255,.85);}
.cards{grid-template-columns:repeat(auto-fill,minmax(340px,1fr));gap:30px;}
.card{border:0;border-radius:0;background:transparent;}
.card:hover{transform:none;} .card .img{aspect-ratio:3/2;border-radius:4px;}
.card .img img{transition:transform .5s ease;} .card:hover .img img{transform:scale(1.04);}
.card .txt{padding:16px 2px 0;}
.section.sky,.sec.sky{background:#fff;}
.gallery{columns:2 420px;column-gap:22px;} .gallery .ph{border-radius:4px;}
@media (max-width:520px){.cards{grid-template-columns:1fr;}}

kleurrijk.css:
body{font-family:'Nunito','Segoe UI',Arial,sans-serif;}
h1,h2,h3{font-family:'Baloo 2','Nunito',sans-serif;font-weight:800;letter-spacing:0;line-height:1.02;}
.btn,.menu a.cta{border-radius:999px;}
.hero,.crumb,.shero,.chero,.phero,.thx{background:var(--blue);}
.hero::after{border-color:#fff;opacity:.16;}
.eyebrow,.shero .eyebrow{color:rgba(255,255,255,.9);} .eyebrow::before,.shero .eyebrow::before{background:#fff;}
.hero .lead,.crumb p,.shero p,.chero p,.phero p,.thx p{color:rgba(255,255,255,.9);}
.hero .btn.primary,.shero .btn.primary,.thx .btn.primary{background:#fff;color:var(--navy);}
.crumb h1 .count{background:var(--navy);}
.servicebar{background:var(--navy);}
.service{border:0;border-radius:28px;box-shadow:0 14px 34px -22px rgba(0,0,0,.45);}
.service .num{border-radius:50%;}
.service:nth-child(4n+1) .num{background:var(--blue);} .service:nth-child(4n+2) .num{background:#f59e0b;} .service:nth-child(4n+3) .num{background:#10b981;} .service:nth-child(4n) .num{background:#8b5cf6;}
.card{border:0;border-radius:26px;box-shadow:0 14px 34px -22px rgba(0,0,0,.45);}
.card .img{border-radius:26px 26px 0 0;}
.folder .tab{border-radius:22px 22px 0 0;} .folder .body{border-radius:0 30px 30px 30px;} .photo-sheet,.photo-sheet img{border-radius:20px;}
.band{background:var(--navy);}
.cform,.cside{border-radius:28px;} .others a{border-radius:999px;}
.gallery .ph{border-radius:24px;}
.filters a.on{color:var(--blue);}
